# Reads the CSVs generated by the Python script and creates a named list by series_id.
# Usage: Rscript criar_lista.R

metadata <- read.csv("synthetic_series/metadata.csv")
series   <- read.csv("synthetic_series/series.csv")

ids <- unique(metadata$series_id)

data <- setNames(
  lapply(ids, function(id) {
    list(
      metadata = metadata[metadata$series_id == id, ],
      values   = series[series$series_id == id, c("time", "value", "is_anomaly")]
    )
  }),
  as.character(ids)
)

saveRDS(data, "synthetic_series/series_list.RDS")
cat("Saved:", length(data), "series to synthetic_series/series_list.RDS\n")
